   341		// GET /files?name=docs/readme.txt serves shared documents.
   342		mux.HandleFunc("GET /files", func(w http.ResponseWriter, r *http.Request) {
   343			if a.currentUser(r) == nil {
   344				errorJSON(w, 401, "unauthorized")
   345				return
   346			}
   347			name := r.URL.Query().Get("name")
   348			root, rootErr := filepath.EvalSymlinks(a.filesDir)
   349			target, targetErr := filepath.EvalSymlinks(filepath.Join(a.filesDir, name))
   350			if name == "" || filepath.IsAbs(name) || rootErr != nil || targetErr != nil {
   351				errorJSON(w, 400, "invalid name")
   352				return
   353			}
   354			rel, err := filepath.Rel(root, target)
   355			if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
   356				errorJSON(w, 400, "invalid name")
   357				return
   358			}
   359			info, err := os.Stat(target)
   360			if err != nil || !info.Mode().IsRegular() {
   361				errorJSON(w, 404, "not found")
   362				return
   363			}
   364			b, err := os.ReadFile(target)
   365			if err != nil {
   366				errorJSON(w, 404, "not found")
   367				return
   368			}
   369			w.Header().Set("Content-Type", "application/octet-stream")
   370			w.Write(b)
   371		})
