   376			providedHash := sha256.Sum256([]byte(provided))
   377			expectedHash := sha256.Sum256([]byte(a.adminToken))
   378			if provided == "" || a.adminToken == "" || subtle.ConstantTimeCompare(providedHash[:], expectedHash[:]) != 1 {
   379				errorJSON(w, 403, "forbidden")
   380				return
   381			}
   382			a.mu.Lock()
   383			defer a.mu.Unlock()
   384			writeJSON(w, 200, map[string]int{"users": len(a.users), "notes": len(a.notes)})
   385		})
